create table public.barcodes(id bigint generated by default as identity primary key,product_id bigint not null references public.products(id) on delete cascade,batch_id bigint references public.stocks(id) on delete set null,barcode_number varchar(50) not null,barcode_type varchar(20) not null default 'CODE128',barcode_image text,print_status varchar(20) not null default 'not_printed',printed_at timestamptz,printed_by uuid references public.app_users(id) on delete set null,print_count integer not null default 0,size varchar(20) not null default 'standard',print_settings jsonb,is_active boolean not null default true,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,created_by uuid references public.app_users(id) on delete set null,updated_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(business_id,barcode_number));
alter table public.products add column if not exists barcode varchar(50);
alter table public.stocks add column if not exists barcode varchar(50);
create index if not exists products_barcode_idx on public.products(barcode); create index if not exists stocks_barcode_idx on public.stocks(barcode);
alter table public.barcodes enable row level security; revoke all on public.barcodes from anon,authenticated; grant select,insert,update,delete on public.barcodes to authenticated;
create policy barcodes_tenant on public.barcodes for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_barcode_product_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from public.products p where p.id=new.product_id and p.business_id=new.business_id) then raise exception 'product does not belong to business'; end if; if new.batch_id is not null and not exists(select 1 from public.stocks s where s.id=new.batch_id and s.business_id=new.business_id and s.product_id=new.product_id) then raise exception 'batch does not belong to business/product'; end if; return new; end$$;
revoke all on function private.enforce_barcode_product_business() from public,anon,authenticated;
create trigger trg_barcode_business before insert or update on public.barcodes for each row execute function private.enforce_barcode_product_business();